
.board {
  padding: 8px 10px 9px;
  display: flex;
  flex-direction: column;
}

.head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 5px;
  margin-bottom: 4px;
  border-bottom: 1px solid var(--c-border);
}

.fallen {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
}

.fallen b {
  font-family: var(--font-accent);
  font-size: 19px;
  line-height: 1.2;
  color: var(--c-accent);
  font-variant-numeric: tabular-nums;
}

.fallen i {
  font-style: normal;
  font-size: 10.5px;
  letter-spacing: 1px;
  color: var(--c-accent);
}

.who {
  flex: 1 1 auto;
  min-width: 0;
  font-family: var(--font-accent);
  font-size: 14px;
  letter-spacing: 2px;
  color: var(--c-primary);
  overflow-wrap: anywhere;
}

.who em {
  font-family: var(--font-body);
  font-style: normal;
  font-size: 11px;
  letter-spacing: 0;
  color: var(--c-text-muted);
}

.palace {
  flex: 0 0 auto;
  font-size: 10px;
  color: var(--c-secondary);
  font-variant-numeric: tabular-nums;
}
